-- The quarterly access review's record (docs/plan.md §1.218; SOC 2 CC6.2, CC6.3): `access_review`,
-- one review an operator recorded (the quarter, who, how many people and removals), and
-- `access_review_item`, each person's access to each client as the review found it, with the
-- reviewer's decision. New tables only, so the previous Worker keeps working. Generated by
-- drizzle-kit from packages/db/src/schema.ts and renumbered 0088 (0081–0087 are other Wave X
-- items); the grants, triggers and row-level security at the end are hand-written.
CREATE TABLE "access_review" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"period" text NOT NULL,
	"reviewed_by" uuid NOT NULL,
	"reviewer_email" text NOT NULL,
	"clients" integer NOT NULL,
	"people" integer NOT NULL,
	"removals" integer NOT NULL,
	"note" text DEFAULT '' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "access_review_period_check" CHECK ("access_review"."period" ~ '^[0-9]{4}-Q[1-4]$'),
	CONSTRAINT "access_review_counts_check" CHECK ("access_review"."clients" >= 0 and "access_review"."people" >= 0 and "access_review"."removals" between 0 and "access_review"."people"),
	CONSTRAINT "access_review_note_check" CHECK (char_length("access_review"."note") <= 2000)
);
